const PDF_PROXY_URL="https://dawn-pine-47e3.zwhappyboy.workers.dev"; // Adobe Worker 域名
const PDF_POLL_MS=3000; // 轮询间隔（毫秒）
// ===== Adobe API：上传PDF→创建任务→轮询→下载（docx）=====
async function _adobeConvert(f){let fd=new FormData();fd.append("file",f,f.name);let r=await fetch(PDF_PROXY_URL+"/api/adobe/convert",{method:"POST",body:fd});let d=await r.json();if(!r.ok||!d.jobId)throw new Error(d.error||"创建转换任务失败");return d}
async function _adobeWait(jobId,onProgress){for(;;){let r=await fetch(PDF_PROXY_URL+"/api/adobe/status?jobId="+encodeURIComponent(jobId));let d=await r.json();if(!r.ok)throw new Error(d.error||"查询任务状态失败");if(d.status==="done")return d;if(d.status==="failed")throw new Error("转换失败");if(onProgress)onProgress(d.status);await new Promise(res=>setTimeout(res,PDF_POLL_MS))}}
async function _adobeDownload(url){let r=await fetch(PDF_PROXY_URL+"/api/adobe/download?url="+encodeURIComponent(url));if(!r.ok){let d=await r.json().catch(()=>({}));throw new Error(d.error||"下载文件失败")}let buf=await r.arrayBuffer();return new Blob([buf],{type:"application/vnd.openxmlformats-officedocument.wordprocessingml.document"})}
async function _pymupdfLoader(){if(_pmInstance)return _pmInstance;const CDN='https://cdn.jsdelivr.net/npm/@bentopdf/pymupdf-wasm@0.11.16/';const mod=await import(CDN+'dist/index.js');const{PyMuPDF}=mod;_pmInstance=new PyMuPDF({assetPath:CDN+'assets/',ghostscriptUrl:''});await _pmInstance.load();return _pmInstance}async function _fixDocxTables(blob){if(!window.JSZip)throw new Error("JSZip not loaded");let zip=await JSZip.loadAsync(blob);let docXml=await zip.file("word/document.xml").async("string");
// 移除 pdf2docx 生成的多栏/换栏分节段落，避免表格被拆散左右并排
docXml=docXml.replace(/<w:p><w:pPr><w:sectPr>(?:(?!<\/w:sectPr>)[\s\S])*?(?:<w:cols w:num="[2-9]"|<w:type w:val="nextColumn"\/>)(?:(?!<\/w:sectPr>)[\s\S])*?<\/w:sectPr><\/w:pPr><\/w:p>/g,'');
let borderXml='<w:tblBorders><w:top w:val="single" w:sz="2" w:space="0" w:color="D0D7E5"/><w:left w:val="single" w:sz="2" w:space="0" w:color="D0D7E5"/><w:bottom w:val="single" w:sz="2" w:space="0" w:color="D0D7E5"/><w:right w:val="single" w:sz="2" w:space="0" w:color="D0D7E5"/><w:insideH w:val="single" w:sz="2" w:space="0" w:color="D0D7E5"/><w:insideV w:val="single" w:sz="2" w:space="0" w:color="D0D7E5"/></w:tblBorders>';docXml=docXml.replace(/<w:tblBorders>[\s\S]*?<\/w:tblBorders>/g,'');docXml=docXml.replace(/<\/w:tblPr>/g,borderXml+'<\/w:tblPr>');
// 修复表格宽度：tblGrid 与单元格 tcW 对齐，避免 Word/WPS 重排错乱
let sect=docXml.match(/<w:sectPr>[\s\S]*?<\/w:sectPr>/);let usable=0;if(sect){let pgw=+((/<w:pgSz[^>]*w:w="(\d+)"/).exec(sect[0])||[])[1]||0;let lm=+(/w:left="(\d+)"/.exec(sect[0])||[])[1]||0;let rm=+(/w:right="(\d+)"/.exec(sect[0])||[])[1]||0;usable=pgw-lm-rm}
docXml=docXml.replace(/<w:tbl>[\s\S]*?<\/w:tbl>/g,tb=>{let rows=[...tb.matchAll(/<w:tr>[\s\S]*?<\/w:tr>/g)];if(!rows.length)return tb;let firstCells=[...rows[0][0].matchAll(/<w:tc>[\s\S]*?<\/w:tc>/g)];let tcws=firstCells.map(c=>{let m=(/<w:tcW w:type="\w+" w:w="(\d+)"/).exec(c)||(/<w:tcW w:w="(\d+)" w:type="\w+"/).exec(c);return m?+m[1]:null});let tcwSum=tcws.reduce((s,w)=>s+(w||0),0);let gridCols=[...tb.matchAll(/<w:gridCol w:w="(\d+)"/g)].map(m=>+m[1]);let gridTotal=gridCols.reduce((a,b)=>a+b,0);let indM=(/<w:tblInd[^>]*w:w="([\d.]+)"/).exec(tb);let ind=indM?+indM[1]:0;let target=tcwSum>0?tcwSum:gridTotal;if(usable>0)target=Math.min(target,usable-ind);target=Math.round(Math.max(1,target));let newCols=tcwSum>0?tcws.map(w=>Math.round((w/tcwSum)*target)):gridCols.map(c=>Math.round((c/gridTotal)*target));let diff=target-newCols.reduce((a,b)=>a+b,0);newCols[newCols.length-1]=(newCols[newCols.length-1]||0)+diff;let grid=tb.match(/<w:tblGrid>[\s\S]*?<\/w:tblGrid>/)[0];tb=tb.replace(grid,'<w:tblGrid>'+newCols.map(c=>`<w:gridCol w:w="${c}"/>`).join('')+'</w:tblGrid>');tb=tb.replace(/<w:tblW w:type="auto" w:w="0"\/>/,`<w:tblW w:type="dxa" w:w="${Math.round(target)}"/>`);return tb});zip.file("word/document.xml",docXml);return await zip.generateAsync({type:"blob",mimeType:"application/vnd.openxmlformats-officedocument.wordprocessingml.document"})}
function _download(blob,name){let a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();a.remove()}
