const UNSTRUCTURED_POLL_MS=3000;
async function _unstructExtract(f){let fd=new FormData();fd.append("file",f,f.name);let r=await fetch(UNSTRUCTURED_PROXY_URL+"/api/unstruct/extract",{method:"POST",body:fd});let d=await r.json();if(!r.ok||!d.jobId)throw new Error(d.error||"创建提取任务失败");return d}
async function _unstructWait(jobId,onProgress){for(;;){let r=await fetch(UNSTRUCTURED_PROXY_URL+"/api/unstruct/status?jobId="+encodeURIComponent(jobId));let d=await r.json();if(!r.ok)throw new Error(d.error||"查询任务状态失败");let s=(d.status||"").toLowerCase();if(s==="completed")return d;if(s==="failed")throw new Error("提取失败");if(onProgress)onProgress(d.status);await new Promise(res=>setTimeout(res,UNSTRUCTURED_POLL_MS))}}
async function _unstructDownload(url){let r=await fetch(UNSTRUCTURED_PROXY_URL+"/api/unstruct/download?url="+encodeURIComponent(url));if(!r.ok){let d=await r.json().catch(()=>({}));throw new Error(d.error||"下载结果失败")}let buf=await r.arrayBuffer();return new Blob([buf],{type:"application/json"})}
