function _splitPdfWords(words,pageW){let sorted=[...words].sort((a,b)=>a.x0-b.x0);let cols=[],cur=[];let gap=pageW*0.055;for(let w of sorted){if(cur.length&&w.x0-cur[cur.length-1].x1>gap){cols.push(cur.map(v=>v.t).join(" ").trim());cur=[]}cur.push(w)}if(cur.length)cols.push(cur.map(v=>v.t).join(" ").trim());return cols.filter(Boolean)}
async function _pdf2WordFromText(pdf){let children=[];for(let i=1;i<=pdf.numPages;i++){let page=await pdf.getPage(i);let content=await page.getTextContent();let items=content.items.filter(it=>it.str&&it.str.trim());if(!items.length){if(i<pdf.numPages)children.push(new docx.Paragraph({children:[new docx.TextRun({break:1})]}));continue}let rows=new Map();for(let item of items){let y=Math.round(item.transform[5]);let x=Math.round(item.transform[4]);if(!rows.has(y))rows.set(y,new Map());rows.get(y).set(x,item.str.trim())}let sortedYs=[...rows.keys()].sort((a,b)=>b-a);let rowList=[];for(let y of sortedYs){let sortedXs=[...rows.get(y).keys()].sort((a,b)=>a-b);let row=[];let prevX=null;for(let x of sortedXs){if(prevX!==null&&x-prevX>80)row.push("");row.push(rows.get(y).get(x));prevX=x}rowList.push({row,isTable:row.length>1})}let idx=0;while(idx<rowList.length){if(rowList[idx].isTable){let td=[];while(idx<rowList.length&&rowList[idx].isTable){td.push(rowList[idx].row);idx++}let mc=Math.max(...td.map(r=>r.length));let trs=td.map(r=>{let cells=[];for(let c=0;c<mc;c++)cells.push(new docx.TableCell({children:[new docx.Paragraph({children:[new docx.TextRun(r[c]||"")]})]}));return new docx.TableRow({children:cells})});let b={style:docx.BorderStyle.SINGLE,size:2,color:"999999"};children.push(new docx.Table({rows:trs,borders:{top:b,bottom:b,left:b,right:b,insideHorizontal:b,insideVertical:b}}))}else{let text=rowList[idx].row.join(" ").trim();if(text)children.push(new docx.Paragraph({children:[new docx.TextRun(text)],spacing:{after:80}}));idx++}}if(i<pdf.numPages)children.push(new docx.Paragraph({children:[new docx.TextRun({break:1})]}))}let doc=new docx.Document({sections:[{properties:{},children}]});return await docx.Packer.toBlob(doc)}
async function _pdf2WordOcr(pdf){$("#out").textContent="Scanned PDF detected, loading OCR engine...";if(!window.Tesseract)throw new Error("OCR engine not loaded");let worker=await Tesseract.createWorker(["chi_sim","eng"],1,{logger:m=>{if(m.status==="recognizing text")$("#out").textContent="OCR recognizing... "+Math.round(m.progress*100)+"%"}});let children=[];for(let i=1;i<=pdf.numPages;i++){$("#out").textContent="Rendering page "+i+"/"+pdf.numPages+"...";let page=await pdf.getPage(i);let base=page.getViewport({scale:1});let scale=Math.min(2.5,1600/base.width);let vp=page.getViewport({scale});let cv=document.createElement("canvas");cv.width=vp.width;cv.height=vp.height;let ctx=cv.getContext("2d");await page.render({canvasContext:ctx,viewport:vp}).promise;$("#out").textContent="OCR page "+i+"/"+pdf.numPages+"...";let{data}=await worker.recognize(cv);let words=(data.words||[]).map(w=>({t:(w.text||"").trim(),x0:(w.bbox||{}).x0||0,y0:(w.bbox||{}).y0||0,x1:(w.bbox||{}).x1||0,y1:(w.bbox||{}).y1||0})).filter(w=>w.t);if(!words.length){if(data.text)children.push(new docx.Paragraph({children:[new docx.TextRun(data.text)],spacing:{after:80}}));if(i<pdf.numPages)children.push(new docx.Paragraph({children:[new docx.TextRun({break:1})]}));continue}words.sort((a,b)=>a.y0-b.y0||a.x0-b.x0);let rows=[],curRow=null;for(let w of words){if(!curRow||w.y0-curRow.y0>curRow.h*0.7){if(curRow)rows.push(curRow);curRow={y0:w.y0,h:Math.max(1,w.y1-w.y0),ws:[]}}curRow.ws.push(w);if(w.y1-w.y0>curRow.h)curRow.h=w.y1-w.y0}if(curRow)rows.push(curRow);let pageW=vp.width;let rowsCols=rows.map(r=>({text:r.ws.map(v=>v.t).join(" "),cols:_splitPdfWords(r.ws,pageW)}));let tableRows=rowsCols.filter(r=>r.cols.length>1);let useTable=tableRows.length>=2&&tableRows.length>=rows.length*0.5;if(useTable){let nCols=Math.max(...tableRows.map(r=>r.cols.length));let trs=rowsCols.map(r=>{let cells=[];for(let c=0;c<nCols;c++)cells.push(new docx.TableCell({children:[new docx.Paragraph({children:[new docx.TextRun(r.cols[c]||"")]})]}));return new docx.TableRow({children:cells})});let b={style:docx.BorderStyle.SINGLE,size:2,color:"999999"};children.push(new docx.Table({rows:trs,borders:{top:b,bottom:b,left:b,right:b,insideHorizontal:b,insideVertical:b}}))}else{for(let r of rowsCols){if(r.text)children.push(new docx.Paragraph({children:[new docx.TextRun(r.text)],spacing:{after:80}}))}}if(i<pdf.numPages)children.push(new docx.Paragraph({children:[new docx.TextRun({break:1})]}))}await worker.terminate();let doc=new docx.Document({sections:[{properties:{},children}]});return await docx.Packer.toBlob(doc)}
async function _pdf2WordLocal(f){if(!window.pdfjsLib)throw new Error("PDF.js not loaded");if(!window.docx)throw new Error("docx.js not loaded");$("#out").textContent="Loading PDF for local processing...";let buf=await f.arrayBuffer();let pdf=await pdfjsLib.getDocument({data:buf}).promise;let totalChars=0;for(let i=1;i<=pdf.numPages;i++){let page=await pdf.getPage(i);let content=await page.getTextContent();totalChars+=content.items.reduce((s,item)=>s+(item.str||"").length,0)}if(totalChars<pdf.numPages*8){return await _pdf2WordOcr(pdf)}else{$("#out").textContent="Extracting text from PDF...";return await _pdf2WordFromText(pdf)}}
function render(){const x=T[lang]||T.en;document.querySelectorAll("[data-t]").forEach(e=>{e.textContent=x[e.dataset.t]||T.en[e.dataset.t]||e.textContent});$("#search").placeholder=x.search;$("#lang").value=lang;document.documentElement.lang=lang;draw(tools)}
function draw(list){$("#grid").innerHTML=list.map(t=>`<article class="card" data-id="${t[0]}"><div class="icon">${t[1]}</div><h3>${tName(t[0])}</h3><p>${tDesc(t[0])}</p></article>`).join("");document.querySelectorAll(".card").forEach(e=>e.onclick=()=>open(e.dataset.id));$("#cats").innerHTML=(CATS_I18N[lang]||CATS_I18N.en).map(c=>`<div class="cat" data-cat="${c[0]}">${c[1]}</div>`).join("");document.querySelectorAll(".cat").forEach(e=>e.onclick=()=>draw(tools.filter(t=>t[2]===e.dataset.cat)))}
$("#search").oninput=e=>{let q=e.target.value.toLowerCase();draw(tools.filter(t=>(tName(t[0])+tDesc(t[0])+t[2]).toLowerCase().includes(q)))};$("#lang").onchange=e=>{lang=e.target.value;localStorage.lang=lang;render()};$("#theme").onclick=()=>{document.body.classList.toggle("dark");localStorage.dark=document.body.classList.contains("dark")};if(localStorage.dark==="true")document.body.classList.add("dark");$("#close").onclick=()=>$("#modal").classList.remove("show");$("#brand").onclick=()=>{$("#modal").classList.remove("show");$("#search").value="";draw(tools);window.scrollTo({top:0,behavior:"smooth"})};
